        O3["Child B"]
        O4["Grandchild A1"]
        O5["Grandchild A2"]
        O6["Grandchild B1"]
    end

    O1 -->|"⏭ skip"| O2
    O1 -->|"✅ check"| O3
    O2 -.->|"⏭ skip"| O4
    O2 -.->|"⏭ skip"| O5
    O3 -->|"✅ check"| O6

    style D1 fill:#c8e6c9
