```csharp
// ══════════════════════════════════════
// Abstract Products
// ══════════════════════════════════════
public interface IButton
{
    string Render();
    string OnClick();
}

public interface ICheckbox
{
    string Render();
    string OnToggle(bool isChecked);
}

public interface ITextField
{
