## 1.3 Promises Deep Dive

```javascript
// === IMPLEMENTING A PROMISE FROM SCRATCH ===
class MyPromise {
  #state = "pending";   // pending | fulfilled | rejected
  #value = undefined;
  #handlers = [];

  constructor(executor) {
    const resolve = (value) => {
      if (this.#state !== "pending") return;

      // Handle thenable/promise resolution
      if (value && typeof value.then === "function") {
        value.then(resolve, reject);
        return;
      }

      this.#state = "fulfilled";
      this.#value = value;
      this.#processHandlers();
    };

    const reject = (reason) => {
      if (this.#state !== "pending") return;
      this.#state = "rejected";
      this.#value = reason;
      this.#processHandlers();
    };

    try {
      executor(resolve, reject);
    } catch (err) {
      reject(err);
    }
  }

  then(onFulfilled, onRejected) {
    return new MyPromise((resolve, reject) => {
      this.#handlers.push({
        onFulfilled: typeof onFulfilled === "function" ? onFulfilled : (v) => v,
        onRejected: typeof onRejected === "function" ? onRejected : (e) => { throw e; },
        resolve,
        reject,
      });
      this.#processHandlers();
    });
  }

  catch(onRejected) {
    return this.then(null, onRejected);
  }

  finally(callback) {
    return this.then(
      (value) => MyPromise.resolve(callback()).then(() => value),
      (reason) => MyPromise.resolve(callback()).then(() => { throw reason; })
    );
  }

  #processHandlers() {
    if (this.#state === "pending") return;

    // Microtask scheduling
    queueMicrotask(() => {
      for (const handler of this.#handlers) {
        const fn = this.#state === "fulfilled" ? handler.onFulfilled : handler.onRejected;
        try {
          const result = fn(this.#value);
          handler.resolve(result);
        } catch (err) {
          handler.reject(err);
        }
      }
      this.#handlers = [];
    });
  }

  // Static methods
  static resolve(value) { return new MyPromise(res => res(value)); }
  static reject(reason) { return new MyPromise((_, rej) => rej(reason)); }

  static all(promises) {
    return new MyPromise((resolve, reject) => {
      const results = [];
      let remaining = promises.length;
      if (remaining === 0) return resolve([]);

      promises.forEach((p, i) => {
        MyPromise.resolve(p).then(
          (value) => {
            results[i] = value;
            if (--remaining === 0) resolve(results);
          },
          reject
        );
      });
    });
  }

  static allSettled(promises) {
    return MyPromise.all(
      promises.map(p =>
        MyPromise.resolve(p)
          .then(value => ({ status: "fulfilled", value }))
          .catch(reason => ({ status: "rejected", reason }))
      )
    );
  }

  static race(promises) {
    return new MyPromise((resolve, reject) => {
      promises.forEach(p => MyPromise.resolve(p).then(resolve, reject));
    });
  }

  static any(promises) {
    return new MyPromise((resolve, reject) => {
      const errors = [];
      let remaining = promises.length;

      promises.forEach((p, i) => {
        MyPromise.resolve(p).then(resolve, (err) => {
          errors[i] = err;
          if (--remaining === 0) {
            reject(new AggregateError(errors, "All promises were rejected"));
          }
        });
      });
    });
  }
}
```

